        setSelectMenuValue(LABEL_COLOR_SELECT_MENU, (_vis && _vis.colorId) || DEFAULT);
        setSelectMenuValue(NODE_SHAPE_SELECT_MENU, DEFAULT);
        removeColorLegend(LEGEND_LABEL_COLOR);
