    function layoutButtonClicked() {
        _state.circularDisplay = getCheckboxValue(LAYOUT_CIRC_BUTTON);
        _state.unrootedDisplay = getCheckboxValue(LAYOUT_UNROOTED_BUTTON);
        syncZoomRowButtons();
        zoomToFit();
    }

    // While the circular layout is on, X-/X+ wear the desktop's rotate faces
    // and rotate the display; in the rectangular layout they are the plain
    // horizontal zoom pair. Same buttons, same bindings -- only the face and
    // the meaning change with the layout.
    function syncZoomRowButtons() {
        // layout-restricted controls, as on the desktop: unrooted has no
        // common label edge to align to and no even row spacing to auto-hide
        // against; an alignment / time axis is inherently horizontal. Synced
        // BEFORE the zoom-row early return, and (via updateButtonEnabledState)
        // on every render, so subtree switches keep them honest.
        let phyBtn = byId(PHYLOGRAM_BUTTON);
        if (phyBtn) {
            phyBtn.disabled = _basicTreeProperties.branchLengths !== true;
        }
        let alignBtn = byId(PHYLOGRAM_ALIGNED_BUTTON);
        if (alignBtn) {
            alignBtn.disabled = _state.unrootedDisplay || _basicTreeProperties.branchLengths !== true;
        }
        let dyna = byId(DYNAHIDE_CB);
        if (dyna) {
            dyna.disabled = _state.unrootedDisplay;
        }
        let msaCb = byId(MSA_CB);
        if (msaCb) {
            msaCb.disabled = radialDisplay();
        }
        let timeCb = byId(TIME_AXIS_CB);
        if (timeCb) {
            timeCb.disabled = radialDisplay();
        }
        let timeGridCb = byId(TIME_GRID_CB);
        if (timeGridCb) {
            // grid lines hang off the time axis: no axis, nothing to grid
            timeGridCb.disabled = radialDisplay() || _state.showTimeAxis !== true;
        }
        let minus = byId(ZOOM_OUT_X);
        let plus = byId(ZOOM_IN_X);
        let expandV = byId(ZOOM_TO_EXPAND_Y);
        let fitW = byId(FIT_WIDTH_BUTTON);
        if (!minus || !plus || !expandV || !fitW) {
            return;
        }
        let yIn = byId(ZOOM_IN_Y);
        let yOut = byId(ZOOM_OUT_Y);
        if (radialDisplay()) {
            // both axes of a circle are its one diameter, so the Y pair
            // becomes the plain +/- zoom, as on the desktop
            if (yIn) {
                yIn.value = '+';
                yIn.title = 'zoom in (or mousewheel over the tree)';
            }
            if (yOut) {
                yOut.value = '-';
                yOut.title = 'zoom out (or mousewheel over the tree)';
            }
            minus.innerHTML = makeGlyph('rotate_ccw');
            minus.title = 'rotate counter-clockwise';
            plus.innerHTML = makeGlyph('rotate_cw');
            plus.title = 'rotate clockwise';
            // as on the desktop: no vertical expansion in circular, and the
            // fit-width slot -- redundant with fit there, a circle has just
            // its one diameter -- becomes the label-direction flip. Its face
            // shows the direction a click switches TO, its tooltip the
            // current one.
            expandV.disabled = true;
            fitW.disabled = false;
            fitW.innerHTML = makeGlyph(_radialLabelsHorizontal ? 'labels_radial' : 'labels_horizontal');
            fitW.title = 'node labels: ' + (_radialLabelsHorizontal ? 'horizontal' : 'radial')
                + ' -- click to flip';
        } else {
            if (yIn) {
                yIn.value = 'Y+';
                yIn.title = 'zoom in vertically (or Shift+mousewheel)';
            }
            if (yOut) {
                yOut.value = 'Y-';
                yOut.title = 'zoom out vertically (or Shift+mousewheel)';
            }
            minus.textContent = 'X-';
            minus.title = 'zoom out horizontally (or Shift+Alt+mousewheel)';
            plus.textContent = 'X+';
            plus.title = 'zoom in horizontally (or Shift+Alt+mousewheel)';
            expandV.disabled = false;
            fitW.disabled = false;
            fitW.innerHTML = makeGlyph('fit_width');
            fitW.title = 'fit the tree to the window width, keeping the current vertical zoom';
        }
    }

